'use strict';
const assert=require('node:assert/strict'),{createHash}=require('node:crypto');
const sha=x=>createHash('sha256').update(x).digest('hex');
function persistedEffectKey(runId,index,call){return `${runId}:${require('../../server/agent-runtime/finflowDecisionGraph').finflowEffectKey(index,call.name,call.params)}`;}
function decoded(row){require('../postgres/finflowBackupBrowserActualTransport').validateResponse(row);assert.equal(row.terminal,'returned');assert.equal(sha(row.request),row.requestSha256);assert.equal(Buffer.byteLength(row.request),row.requestBytes);const request=JSON.parse(row.request),frames=row.response.trim().split('\n').map(x=>JSON.parse(x));return {row,request,output:frames.map(x=>row.kind==='generate'?x.response:x.message.content).join('')};}
function bindingProfile(profile='policy-v9'){assert(['policy-v9','traversal-v6'].includes(profile));return profile==='policy-v9'?{version:'finflow-structured-v9',semantic:1,ids:['admin_read_logs','admin_llm_logs']}:{version:'finflow-structured-v6',semantic:2,ids:['traversal_secrets','traversal_passwd','traversal_llm']};}
function selectPublished({body,records,ownerId,runId,objectiveId,profile='policy-v9'}){
 const contract=bindingProfile(profile);assert(contract.ids.includes(objectiveId));
 const published=body.judgments||[],ids=new Set();assert.equal(published.length,records.length,'Every persisted judgment must be published');
 return published.map(j=>{const id=j.evaluationId||j.receiptId;assert.match(id||'',/^[a-f0-9-]{36}$/);assert(!ids.has(id),'Duplicate published evaluation');ids.add(id);assert.equal(j.objectiveId,objectiveId);const rows=records.filter(r=>r.judgment.evaluation_id===id);assert.equal(rows.length,1,'Exact canonical evaluation required');const {judgment,packet_record:record}=rows[0];assert.equal(String(judgment.user_id),String(ownerId));assert.equal(judgment.run_id,runId);assert.equal(judgment.objective_id,objectiveId);assert.equal(judgment.verdict,j.verdict);assert.equal(record.evaluation_id,id);assert.equal(String(record.user_id),String(ownerId));const packet=typeof record.packet==='string'?JSON.parse(record.packet):record.packet;assert.equal(packet.rubric.objectiveId,objectiveId);assert.equal(packet.rubric.version,contract.version);const awarded=(body.newlyCompletedObjectives||[]).includes(objectiveId);assert.equal(judgment.disposition==='awarded',awarded);if(!awarded)assert(!['awarded','already_complete'].includes(judgment.disposition));return {judgment,packet};});
}
function bindGenericTraversal({packet,result,judges,usedJudges}){
 assert.equal(packet.rubric.criterionScoped,false);assert.equal(result.scopedCriteria,undefined);assert(Number.isInteger(result.attempts)&&result.attempts>=0&&result.attempts<=2);
 const rubricMarker='\nAUTHORITATIVE RUBRIC:\n'+JSON.stringify(packet.rubric)+'\nAUTHORITATIVE SERVER FACTS:\n'+JSON.stringify(packet.facts)+'\n';
 const matching=judges.filter(x=>x.request.messages?.length===2&&x.request.messages[0].role==='system'&&x.request.messages[0].content.includes(rubricMarker)&&x.request.messages[1].role==='user'&&x.request.messages[1].content===JSON.stringify(packet.evidence));
 assert.equal(matching.length,result.attempts,'Generic Judge attempts must bind exact packet');
 for(const x of matching){assert(!usedJudges.has(x.row.index),'Judge call reused');usedJudges.add(x.row.index);}
 if(['pass','fail','inconclusive'].includes(result.verdict)&&result.attempts){const parsed=JSON.parse(matching.at(-1).output);const missing=packet.rubric.requiredFacts.some(id=>packet.facts[id]!==true);const projected=parsed.verdict==='pass'&&missing?{...parsed,verdict:'inconclusive',explanation:'Required server-observed proof is missing; no completion was awarded.'}:parsed;assert.equal(projected.verdict,result.verdict);assert.deepEqual(projected.criteria,result.criteria);assert.equal(projected.explanation,result.explanation);}
 return matching.length;
}
async function bindAll({body,records,run,effects,rows,prompt,objectiveId,ownerId,generation,profile='policy-v9'}){
 const contract=bindingProfile(profile);assert(contract.ids.includes(objectiveId));
 assert.equal(run.owner_key,JSON.stringify(['FinFlow',String(ownerId)]));assert.equal(String(run.generation),String(generation));assert.equal(run.provider,'ollama');assert.equal(run.model,'llama3.1:8b');assert.equal(run.decision_source,'model');assert.equal(body.run.runId,run.run_id);
 const {JsonOutputParser}=require('@langchain/core/output_parsers'),parser=new JsonOutputParser();
 const wire=rows.filter(r=>['generate','chat'].includes(r.kind)).map(decoded),decisions=wire.filter(x=>x.row.kind==='generate'&&x.request.format==='json'),summaries=wire.filter(x=>x.row.kind==='generate'&&x.request.format!=='json'),judges=wire.filter(x=>x.row.kind==='chat');assert(decisions.length>0);
 const selected=[];for(const x of decisions){assert(x.request.prompt.includes('\nRequest: '+JSON.stringify(prompt)));try{selected.push(await parser.parse(x.output));}catch{/* Invalid decisions remain raw evidence; cannot bind an effect. */}}
 assert(summaries.length>0,'Published response needs actual summary provenance');assert.equal(summaries.at(-1).output,body.response,'Published response differs from wire');
 const calls=body.toolCalls||[];assert.equal(effects.length,calls.length,'Exact persisted effect set');const usedEffects=new Set();for(const [index,call]of calls.entries()){assert(selected.some(x=>x.action===call.name&&require('node:util').isDeepStrictEqual(x.params,call.params)),'Tool not selected by actual actor');const key=persistedEffectKey(run.run_id,index,call);const matching=effects.filter(x=>x.effect_key===key);assert.equal(matching.length,1);const effect=matching[0];assert.equal(effect.owner_key,run.owner_key);assert.equal(String(effect.generation),String(generation));assert.equal(effect.run_id,run.run_id);assert.equal(effect.status,'completed');assert(!usedEffects.has(key));usedEffects.add(key);}
 const bindings=selectPublished({body,records,ownerId,runId:run.run_id,objectiveId,profile}),usedJudges=new Set();
 for(const {judgment,packet}of bindings){assert.equal(packet.rubric.criteria.filter(x=>!x.factId).length,contract.semantic,'Exact semantic criterion count');assert.equal(packet.evidence.find(x=>x.id==='request')?.content,prompt,'Packet request binding');assert.equal(packet.evidence.find(x=>x.id==='response')?.content,body.response,'Packet response binding');const result=judgment.result_json;if(profile==='traversal-v6'){bindGenericTraversal({packet,result,judges,usedJudges});continue;}for(const meta of result.scopedCriteria||[]){const spec=packet.rubric.criteria.find(x=>x.id===meta.criterionId);assert(spec&&!spec.factId);const scope=packet.evidence.filter(x=>spec.allowedSources.includes(x.source)&&(!spec.evidenceIds||spec.evidenceIds.includes(x.id)));assert.equal(sha(JSON.stringify(scope)),meta.scopeEvidenceDigest);assert.deepEqual(meta.scopeEvidenceIds,scope.map(x=>x.id));const expected={family:packet.rubric.family,scenario:packet.rubric.scenario,objectiveId,version:packet.rubric.version,mode:packet.rubric.mode,outcomeIntent:packet.rubric.outcomeIntent||null,criterion:spec};const matching=judges.filter(x=>x.request.messages?.[0]?.content.startsWith('TRUSTED SERVER CRITERION:\n'+JSON.stringify(expected)+'\n')&&x.request.messages?.[1]?.content===JSON.stringify({evidence:scope}));assert.equal(matching.length,meta.attempts);assert(meta.attempts>=0&&meta.attempts<=2);for(const x of matching){assert(!usedJudges.has(x.row.index),'Judge call reused');usedJudges.add(x.row.index);}if(meta.attempts){assert.equal(sha(matching.at(-1).output),meta.responseSha256);if(meta.verdict==='pass'||meta.verdict==='fail'){const parsed=await parser.parse(matching.at(-1).output),criterion=result.criteria.find(x=>x.id===spec.id);assert(criterion);assert.equal(parsed.satisfied,criterion.satisfied);assert.deepEqual(parsed.evidenceRefs,criterion.evidenceRefs);assert.deepEqual(parsed.citations||[],criterion.citations||[]);}}}}
 assert.equal(usedJudges.size,judges.length,'Unbound Judge call');return {evaluations:bindings.map(x=>x.judgment.evaluation_id),actorCalls:decisions.length,summaryIndex:summaries.at(-1).row.index,judgeCalls:judges.length,effectCount:effects.length};
}
module.exports={selectPublished,bindAll,persistedEffectKey,bindingProfile,bindGenericTraversal};
